<link rel="stylesheet" href="/static/map.css">
<script src="/static/js/i18n.js" defer></script>
<script src="/static/js/map.js" defer></script>
<script src="/static/js/observer.js" defer></script>
</head>
<body>
<main id="observerApp" class="stage">
<svg id="obsMap" class="map" role="img" aria-label="星图" preserveAspectRatio="xMidYMid meet"></svg>
<header class="corner corner-left" data-i18n="observerBrand">Blackout · 星图</header>
<div id="obsMic" class="corner corner-right" data-i18n="micOffline">未连接</div>
<p id="obsMessage" class="quiet-center" hidden></p>
<p id="obsFinished" class="finished-line" hidden></p>
<aside id="obsParkingPanel" class="parking">
<p class="parking-label" data-i18n="parkingLot">停车场</p>
<ul id="obsParking" class="parking-list"></ul>
</aside>
<footer id="obsSubtitles" class="subtitles">
<p id="obsCaption" class="caption"></p>
<p id="obsReply" class="ai-line"></p>
<p id="obsDecision" class="decision-line"></p>
</footer>
<p id="obsCounters" class="counters"></p>
<section id="posterWrap" class="poster-wrap" hidden>
<p id="posterTitle" class="poster-title"></p>
<img id="posterImage" class="poster-image" data-i18n-alt="posterAlt" alt="成果图">
</section>
</main>
</body>
</html>
", "path": "app/static/observer.html"}, {"content": ":root {
  --night: #000000;
  --dusk: #0b0b0c;
  --star: #f4efe6;
  --star-dim: #8a8478;
  --line: #3a3833;
  --amber: #e8b44c;
  --signal: #e5604d;
  --parked: #7d93b2;
  --paper: #f6f1e7;
  --ink: #1c1a17;
  --ink-dim: #6b655a;
  --rule: #d9d1c1;
  font-family: "PingFang SC", "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans CJK SC", "Segoe UI", system-ui, sans-serif;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { margin: 0; padding: 0; }
body {
  font-family: "PingFang SC", "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans CJK SC", "Segoe UI", system-ui, sans-serif;
  background: var(--dusk);
  color: var(--star);
  min-height: 100vh;
  overflow-x: hidden;
}
.page { max-width: 720px; margin: 0 auto; padding: 48px 20px 56px; }
.start-page { max-width: 1080px; text-align: left; padding-top: 8vh; position: relative; }
.lang-toggle {
  position: absolute; top: 22px; right: 20px; padding: 6px 4px; font-size: 14px;
  color: var(--star-dim); background: transparent;
}
.start-columns { display: grid; grid-template-columns: 0.79fr 1fr; gap: 56px; align-items: start; }
.start-left { min-width: 0; }
.brand { font-size: 14px; letter-spacing: 4px; color: var(--star-dim); margin: 0 0 40px; }
.start-headline {
  font-size: 42px; font-weight: 300; letter-spacing: 1px; line-height: 1.25; margin: 0 0 20px;
  color: var(--star); text-wrap: balance; overflow-wrap: break-word;
}
.headline-line { display: block; }
.start-subline { color: var(--star-dim); font-size: 17px; line-height: 1.8; margin: 0 0 42px; }
.goal-line { display: flex; align-items: flex-end; gap: 6px; border-bottom: 1px solid var(--line); padding-bottom: 8px; }
#goalInput {
  flex: 1 1 auto; min-width: 0; padding: 10px 2px; border: 0; font-size: 19px; font-weight: 300;
  background: transparent; color: var(--star); outline: none; text-align: left;
}
#goalInput::placeholder { color: var(--star-dim); }
.mic-btn { background: transparent; border: 0; color: var(--star-dim); cursor: pointer; padding: 6px; flex: 0 0 auto; }
.mic-btn.recording { color: var(--amber); animation: micPulse 1.2s ease-in-out infinite; }
@keyframes micPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
button, .buttonlike {
  padding: 12px 16px; border: 0; border-radius: 10px; font-size: 16px; cursor: pointer;
  background: transparent; color: var(--star); text-align: center; font-family: inherit;
}
button.primary, .lights-off {
  display: inline-block; margin: 36px 0 6px; width: auto; height: auto; border-radius: 999px;
  padding: 15px 34px; background: var(--star); color: var(--ink); font-size: 18px; font-weight: 400;
  letter-spacing: 1px; box-shadow: 0 0 34px rgba(244, 239, 230, 0.28);
}
button:disabled { opacity: 0.55; cursor: default; }
.quiet-btn { color: var(--star-dim); font-size: 15px; padding: 8px 10px; }
.quiet-line { color: var(--star-dim); line-height: 1.7; margin: 14px 0 0; font-size: 14px; }
.check { display: flex; gap: 8px; align-items: center; justify-content: flex-start; margin-top: 26px; line-height: 1.5; color: var(--star-dim); font-size: 14px; }
.error { color: var(--signal); min-height: 1.4em; line-height: 1.5; font-size: 14px; }
.warning { margin: 12px 0; color: var(--amber); line-height: 1.6; font-size: 14px; background: transparent; border: 0; padding: 0; }
.start-right { min-width: 0; }
.how-sheet {
  margin: 8px 0 0; background: #f3ecdc; padding: 12px;
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.45), 0 4px 14px rgba(0, 0, 0, 0.4);
}
.how-sheet img { display: block; width: 100%; height: auto; aspect-ratio: 1.75; object-fit: cover; }
.start-below { margin-top: 24px; }
.past-toggle { color: var(--star-dim); font-size: 14px; padding: 8px 0; margin-top: 10px; }
.recent { margin-top: 12px; text-align: left; }
.session-item {
  display: flex; gap: 8px; align-items: baseline; background: transparent; border: 0;
  border-top: 1px solid var(--line); border-radius: 0; padding: 14px 2px; margin: 0;
}
.session-goal { flex: 1 1 auto; min-width: 0; overflow-wrap: anywhere; line-height: 1.5; color: var(--star); }
.session-date { color: var(--star-dim); font-size: 13px; flex: 0 0 auto; }
.session-item button { flex: 0 0 auto; padding: 4px 8px; font-size: 14px; color: var(--star-dim); }
#page-black { background: #000000; position: fixed; inset: 0; animation: toBlack 0.5s ease forwards; }
@keyframes toBlack { from { background: var(--dusk); } to { background: #000000; } }
.dot { position: fixed; top: 18px; right: 18px; width: 14px; height: 14px; border-radius: 50%; background: #2a2a2a; }
.dot.paused { background: #2a2a2a; }
.dot.listening { background: #1f3d24; }
.dot.speaking { background: #2a7a3a; }
.dot.reconnecting { background: #5a4a14; }
.hint {
  position: fixed; left: 0; right: 0; bottom: 36px; text-align: center; color: #333333; font-size: 13px; transition: opacity 1s ease;
}
.hint.fading { opacity: 0; }
.result-page { background: var(--paper); color: var(--ink); max-width: 960px; }
body:has(#page-result:not([hidden])) { background: var(--paper); }
.result-page.light-fade { animation: lightOn 0.9s ease forwards; }
@keyframes lightOn { from { background: var(--night); color: var(--star); } to { background: var(--paper); color: var(--ink); } }
#resultTitle { font-size: 38px; font-weight: 300; margin: 0 0 8px; color: var(--ink); line-height: 1.3; }
.result-goal { color: var(--ink-dim); line-height: 1.7; margin: 0 0 12px; }
.result-page .warning { color: var(--amber); }
.result-page .quiet-btn, .result-page .buttonlike { color: var(--ink-dim); }
.summary-block { margin: 10px 0 6px; }
.summary-text { font-size: 20px; line-height: 1.7; color: var(--ink); margin: 0 0 6px; overflow-wrap: anywhere; }
#stopReadingBtn { padding-left: 0; }
.pending-line {
  color: var(--ink-dim); font-size: 18px; line-height: 1.8; margin: 24px 0;
  animation: posterPulse 1.8s ease-in-out infinite;
}
.finish-error-line { color: var(--ink); font-size: 18px; line-height: 1.8; margin: 24px 0 8px; }
.poster-figure { margin: 18px 0 8px; width: 100%; }
.poster-figure img { display: block; width: 100%; height: auto; background: var(--paper); }
.poster-placeholder {
  aspect-ratio: 3 / 2; width: 100%; display: flex; align-items: center; justify-content: center;
  background: #ece4d2; color: var(--ink-dim); font-size: 16px; letter-spacing: 2px;
  animation: posterPulse 1.8s ease-in-out infinite;
}
@keyframes posterPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }
.poster-error { color: var(--signal); line-height: 1.7; margin: 0 0 6px; }
.poster-controls { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-top: 8px; }
.poster-controls a { color: var(--ink-dim); font-size: 15px; padding: 8px 10px 8px 0; text-decoration: none; }
.poster-controls button { color: var(--ink-dim); padding-left: 0; }
.map-hero { width: 100%; margin: 12px 0 8px; }
.map-hero svg { width: 100%; height: auto; display: block; }
.map-hero .map-outline { color: var(--ink); font-size: 16px; line-height: 1.8; padding: 4px 0 4px 2px; }
.map-hero .map-outline ul { margin: 0; padding-left: 22px; }
.map-hero .map-outline li { overflow-wrap: anywhere; color: var(--ink); }
.map-hero .map-outline li > span { overflow-wrap: anywhere; }
.result-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 0 40px; }
.sec { background: transparent; border: 0; border-top: 1px solid var(--rule); border-radius: 0; padding: 18px 0; margin: 0; }
.sec h3 { font-size: 13px; letter-spacing: 2px; margin: 0 0 10px; color: var(--ink-dim); font-weight: 400; }
.sec p, .sec li { line-height: 1.8; overflow-wrap: anywhere; color: var(--ink); }
.sec ul { margin: 0; padding-left: 20px; }
.sec details { margin-top: 6px; }
.sec a { overflow-wrap: anywhere; color: var(--ink); }
.evidence-btn {
  background: transparent; border: 0; border-radius: 0; padding: 0; margin: 0; font-size: inherit;
  line-height: inherit; color: var(--ink); text-align: left; cursor: pointer;
}
.evidence-quote { color: var(--ink-dim); line-height: 1.7; margin-top: 4px; overflow-wrap: anywhere; font-size: 15px; }
.transcript-sec summary { cursor: pointer; color: var(--ink-dim); font-size: 14px; line-height: 1.8; }
.transcript-sec ul { margin-top: 10px; }
.result-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; border-top: 1px solid var(--rule); padding-top: 20px; margin-top: 8px; }
.result-actions .quiet-btn, .result-actions .buttonlike { color: var(--ink-dim); }
.result-actions button.primary.ink-btn {
  width: auto; height: auto; margin: 0; border-radius: 999px; padding: 12px 22px;
  background: var(--ink); color: var(--paper); font-size: 16px; letter-spacing: 0; box-shadow: none;
}
.empty-line { color: var(--ink-dim); line-height: 1.8; }
@media (max-width: 800px) {
  .start-columns { grid-template-columns: 1fr; gap: 28px; }
  .start-page { padding-top: 48px; }
  .start-headline { font-size: 34px; }
  .how-sheet { width: 100%; }
}
@media (max-width: 640px) { .result-columns { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) {
  .mic-btn.recording { animation: none; }
  #page-black { animation: none; }
  .result-page.light-fade { animation: none; }
  .hint { transition: none; }
  .poster-placeholder { animation: none; }
  .pending-line { animation: none; }
}
", "path": "app/static/app.css"}, {"content": ":root {
  --night: #000000;
  --dusk: #0b0b0c;
  --star: #f4efe6;
  --star-dim: #8a8478;
  --line: #3a3833;
  --amber: #e8b44c;
  --signal: #e5604d;
  --parked: #7d93b2;
  --paper: #f6f1e7;
  --ink: #1c1a17;
  --ink-dim: #6b655a;
  --rule: #d9d1c1;
}
* {
  box-sizing: border-box;
}
[hidden] {
  display: none !important;
}
html,
body {
  margin: 0;
  padding: 0;
}
body {
  background: var(--night);
  color: var(--star);
  height: 100vh;
  overflow: hidden;
  font-family: "PingFang SC", "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans CJK SC", "Segoe UI", system-ui, sans-serif;
}
.stage {
  position: fixed;
  inset: 0;
  background: var(--night);
  overflow: hidden;
}
#obsMap,
.stage svg.map,
.stage svg.map-night {
  position: absolute;
  top: 44px;
  bottom: 150px;
  right: 250px;
  left: 0;
  width: calc(100% - 250px);
  height: calc(100% - 194px);
  display: block;
  transition: opacity 1.2s ease;
}
#obsMap.map-faded {
  opacity: 0;
}
.corner {
  position: absolute;
  top: 18px;
  font-size: 14px;
  letter-spacing: 2px;
  color: var(--star-dim);
  z-index: 3;
}
.corner-left {
  left: 22px;
}
.corner-right {
  right: 22px;
  letter-spacing: 1px;
}
.corner-right.mic-ai {
  color: var(--amber);
}
.quiet-center {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--star-dim);
  font-size: 22px;
  font-weight: 300;
  padding: 24px;
  margin: 0;
  z-index: 2;
}
.finished-line {
  position: absolute;
  top: 52px;
  left: 0;
  right: 250px;
  text-align: center;
  margin: 0;
  font-size: 28px;
  font-weight: 300;
  color: var(--star);
  animation: fadeIn 1.2s ease forwards;
  z-index: 3;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.parking {
  position: absolute;
  right: 22px;
  top: 52px;
  width: 200px;
  z-index: 3;
}
.parking-label {
  color: var(--parked);
  font-size: 14px;
  letter-spacing: 3px;
  margin: 0 0 12px;
}
.parking-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.parking-list li {
  color: var(--parked);
  font-size: 16px;
  line-height: 1.6;
  margin: 0 0 10px;
  overflow-wrap: anywhere;
}
.parking-list li.new {
  color: var(--amber);
  animation: parkedIn 2.5s ease forwards;
}
@keyframes parkedIn {
  0% {
    opacity: 0;
    transform: translateX(-46vw);
    color: var(--amber);
  }
  35% {
    opacity: 1;
    transform: translateX(0);
    color: var(--amber);
  }
  80% {
    color: var(--amber);
  }
  100% {
    color: var(--parked);
  }
}
.subtitles {
  position: absolute;
  left: 12%;
  right: 12%;
  bottom: 42px;
  max-height: 108px;
  overflow: hidden;
  text-align: center;
  z-index: 3;
  transition: opacity 1s ease;
}
.subtitles.faded {
  opacity: 0;
}
.caption {
  margin: 0;
  font-size: 26px;
  font-weight: 300;
  line-height: 1.5;
  color: var(--star);
  overflow-wrap: anywhere;
}
.ai-line {
  margin: 8px 0 0;
  font-size: 24px;
  font-weight: 300;
  line-height: 1.5;
  color: var(--amber);
  overflow-wrap: anywhere;
}
.decision-line {
  margin: 6px 0 0;
  font-size: 14px;
  color: var(--star-dim);
}
.counters {
  position: absolute;
  left: 22px;
  bottom: 18px;
  margin: 0;
  font-size: 13px;
  color: var(--star-dim);
  z-index: 3;
}
.poster-wrap {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: var(--night);
  opacity: 0;
  transition: opacity 1.2s ease;
  padding: 20px;
}
.poster-wrap.visible {
  opacity: 1;
}
.poster-title {
  margin: 0 0 16px;
  font-size: 28px;
  font-weight: 300;
  color: var(--star);
  text-align: center;
  overflow-wrap: anywhere;
}
.poster-image {
  display: block;
  max-width: calc(100vw - 40px);
  max-height: calc(100vh - 110px);
  width: auto;
  height: auto;
  object-fit: contain;
}
@media (prefers-reduced-motion: reduce) {
  .parking-list li.new {
    animation: none;
    color: var(--parked);
  }
  .finished-line {
    animation: none;
  }
  .subtitles {
    transition: none;
  }
  #obsMap,
  .poster-wrap {
    transition: none;
  }
}
", "path": "app/static/observer.css"}, {"content": ""use strict";
window.BlackoutStart = (function () {
  const STORAGE_KEY = "blackout_active_session_id";
  const TWO_HOURS_MS = 2 * 60 * 60 * 1000;
  let goalRecorder = null;
  let goalRecording = false;
  let goalStarting = false;
  let starting = false;
  let startGeneration = 0;
  let pastOpen = false;
  let pastCount = 0;
  function el(id) { return document.getElementById(id); }
  function t(key, values) { return window.BlackoutI18n.t(key, values); }
  function errorMessage(data) {
    if (data && data.error && data.error.code) {
      const key = "error_" + String(data.error.code);
      if (window.BlackoutI18n.has(key)) { return t(key); }
    }
    if (data && data.error && data.error.message) { return String(data.error.message); }
    return t("networkError");
  }
  function primeAudio() {
    window.BlackoutCues.ensure();
    if (window.BlackoutCapture && window.BlackoutCapture.prime) { window.BlackoutCapture.prime(); }
    window.BlackoutSpeech.prime();
  }
  function setStartButtonsDisabled(disabled) {
    ["startBtn", "continueLastBtn", "micBtn", "langToggle"].forEach(function (id) {
      const node = el(id);
      if (node) { node.disabled = disabled; }
    });
  }
  async function ensureMic(generation) {
    try { await window.BlackoutCapture.ensurePermission(); }
    catch (e) {
      if (generation !== startGeneration) { return false; }
      if (e && e.name === "NotFoundError") { el("startErr").textContent = t("noMic"); }
      else { el("startErr").textContent = t("micNeeded"); }
      return false;
    }
    return generation === startGeneration;
  }
  function storedId() {
    try { return window.localStorage.getItem(STORAGE_KEY) || ""; } catch (e) { return ""; }
  }
  function clearStored() {
    try { window.localStorage.removeItem(STORAGE_KEY); } catch (e) {}
  }
  async function fetchJson(url, options) {
    const response = await fetch(url, options || {});
    const data = await response.json();
    if (!response.ok) { throw new Error(errorMessage(data)); }
    return data;
  }
  function applySessionLanguage(record) {
    const value = record && String(record.language || "");
    if (value === "zh" || value === "en") { window.BlackoutI18n.set(value, false); }
    updateLangChrome();
  }
  async function openFinished(id) {
    const record = await fetchJson("/api/sessions/" + id);
    if (record.result) {
      applySessionLanguage(record);
      clearStored();
      const result = record.result;
      if (!result.poster && record.poster) { result.poster = record.poster; }
      if (!result.map && record.map) { result.map = record.map; }
      window.BlackoutResult.showResult(result, id);
    }
  }
  async function enterActive(id, resumed, goal) {
    if (starting) { return; }
    starting = true;
    const generation = ++startGeneration;
    primeAudio();
    setStartButtonsDisabled(true);
    try {
      if (!await ensureMic(generation)) { return; }
      if (generation !== startGeneration) { return; }
      try { window.localStorage.setItem(STORAGE_KEY, id); } catch (e) {}
      window.BlackoutBlack.enter(id, resumed, String(goal || ""));
    } finally {
      starting = false;
      setStartButtonsDisabled(false);
    }
  }
  function makeSessionButton(text, handler) {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = text;
    button.addEventListener("click", handler);
    return button;
  }
  function formatDate(value) {
    try {
      const date = new Date(String(value || ""));
      if (isNaN(date.getTime())) { return ""; }
      const locale = window.BlackoutI18n.lang() === "zh" ? "zh-CN" : "en-US";
      return date.toLocaleDateString(locale) + " " + date.toLocaleTimeString(locale, { hour: "2-digit", minute: "2-digit" });
    } catch (e) { return ""; }
  }
  function renderPastToggle() {
    const toggle = el("pastToggle");
    toggle.hidden = pastCount === 0;
    toggle.textContent = t("pastSessions", { count: pastCount });
    const section = el("recentSection");
    if (section) { section.hidden = !pastOpen || pastCount === 0; }
  }
  async function validateContinue() {
    const button = el("continueLastBtn");
    const id = storedId();
    if (!id) { button.hidden = true; return null; }
    let record = null;
    try { record = await fetchJson("/api/sessions/" + id); }
    catch (e) { clearStored(); button.hidden = true; return null; }
    const updated = new Date(String(record.updated_at || record.created_at || "")).getTime();
    const fresh = !isNaN(updated) && Date.now() - updated <= TWO_HOURS_MS;
    if (record.status !== "active" || !fresh) { clearStored(); button.hidden = true; return null; }
    button.hidden = false;
    return record;
  }
  async function refreshList() {
    const box = el("recentList");
    box.replaceChildren();
    pastOpen = false;
    pastCount = 0;
    renderPastToggle();
    await validateContinue();
    try {
      const data = await fetchJson("/api/sessions");
      const sessions = data.sessions || [];
      pastCount = sessions.length;
      renderPastToggle();
      sessions.forEach(function (session) {
        const item = document.createElement("div");
        item.className = "session-item";
        const goal = document.createElement("span");
        goal.className = "session-goal";
        goal.textContent = String(session.goal || "");
        item.appendChild(goal);
        const date = document.createElement("span");
        date.className = "session-date";
        date.textContent = formatDate(session.updated_at || session.created_at);
        item.appendChild(date);
        if (session.status === "finished") {
          item.appendChild(makeSessionButton(t("view"), function () { primeAudio(); openFinished(String(session.id)); }));
        } else {
          const label = t("continueButton");
          item.appendChild(makeSessionButton(label, function () { primeAudio(); enterActive(String(session.id), true, String(session.goal || "")); }));
        }
        item.appendChild(makeSessionButton(t("deleteButton"), async function () {
          if (!window.confirm(t("deleteConfirm"))) { return; }
          await fetch("/api/sessions/" + session.id, { method: "DELETE" });
          if (storedId() === String(session.id)) { clearStored(); }
          refreshList();
        }));
        box.appendChild(item);
      });
    } catch (e) {}
  }
  function setMicRecording(on) {
    const btn = el("micBtn");
    btn.classList.toggle("recording", Boolean(on));
    btn.setAttribute("aria-label", on ? t("stopReading") : t("goalPlaceholder"));
  }
  async function stopGoalRecorder(send) {
    if (!goalRecording || !goalRecorder) { return; }
    goalRecording = false;
    const recorder = goalRecorder;
    goalRecorder = null;
    setMicRecording(false);
    if (!send) { await recorder.cancel(); return; }
    const wav = await recorder.stop();
    const form = new FormData();
    form.append("audio", wav, "goal.wav");
    try {
      const url = "/api/transcribe?language=" + encodeURIComponent(window.BlackoutI18n.lang());
      const data = await fetchJson(url, { method: "POST", body: form });
      el("goalInput").value = String(data.transcript || "");
    } catch (e) {
      el("startErr").textContent = String((e && e.message) || t("didntCatch"));
    }
  }
  async function toggleGoalMic() {
    if (goalStarting || starting) { return; }
    if (goalRecording) { await stopGoalRecorder(true); return; }
    goalStarting = true;
    goalRecorder = window.BlackoutCapture.createWavRecorder();
    try {
      const opened = await goalRecorder.start();
      if (!opened) { goalRecorder = null; goalStarting = false; return; }
      goalRecording = true;
      setMicRecording(true);
      el("startErr").textContent = t("goalRecording");
    } catch (e) {
      goalRecorder = null;
      setMicRecording(false);
      el("startErr").textContent = t("micNeeded");
    }
    goalStarting = false;
  }
  async function startNew() {
    if (starting) { return; }
    starting = true;
    const generation = ++startGeneration;
    primeAudio();
    setStartButtonsDisabled(true);
    try {
      const goal = el("goalInput").value.trim();
      el("startErr").textContent = "";
      if (!goal) { el("startErr").textContent = t("goalRequired"); return; }
      if (!await ensureMic(generation)) { return; }
      if (generation !== startGeneration) { return; }
      const data = await fetchJson("/api/sessions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ goal: goal, language: window.BlackoutI18n.lang() })
      });
      if (generation !== startGeneration) { return; }
      const id = String(data.session_id);
      try { window.localStorage.setItem(STORAGE_KEY, id); } catch (e) {}
      let skipFullscreen = false;
      if (el("openObserver").checked) {
        skipFullscreen = true;
        window.open("/observer?session=" + encodeURIComponent(id), "_blank");
      }
      window.BlackoutBlack.enter(id, false, goal, { skipFullscreen: skipFullscreen });
    } catch (e) {
      if (generation === startGeneration) { el("startErr").textContent = String((e && e.message) || t("networkError")); }
    } finally {
      starting = false;
      setStartButtonsDisabled(false);
    }
  }
  async function continueLast() {
    if (starting) { return; }
    const record = await validateContinue();
    if (!record) { refreshList(); return; }
    applySessionLanguage(record);
    if (record.status === "finished" && record.result) {
      clearStored();
      const result = record.result;
      if (!result.poster && record.poster) { result.poster = record.poster; }
      if (!result.map && record.map) { result.map = record.map; }
      window.BlackoutResult.showResult(result, storedId());
      return;
    }
    const goal = String((record.state && record.state.goal) || record.goal || "");
    enterActive(String(record.id || storedId()), true, goal);
  }
  function backToStart() {
    el("page-black").hidden = true;
    el("page-result").hidden = true;
    el("page-start").hidden = false;
    refreshList();
  }
  async function refreshVoiceWarning() {
    const has = await window.BlackoutSpeech.hasVoice(window.BlackoutI18n.lang());
    el("voiceWarning").hidden = has;
  }
  function updateLangChrome() {
    window.BlackoutI18n.apply(document);
    const toggle = el("langToggle");
    if (toggle) { toggle.textContent = window.BlackoutI18n.lang() === "zh" ? "English" : "中文"; }
    const img = el("howItWorksImg");
    if (img) {
      const name = window.BlackoutI18n.lang() === "zh" ? "how_it_works_zh.jpg" : "how_it_works_en.jpg";
      img.src = "/static/" + name;
      img.alt = t("howAlt");
    }
    renderPastToggle();
  }
  function toggleLanguage() {
    const next = window.BlackoutI18n.lang() === "zh" ? "en" : "zh";
    window.BlackoutI18n.set(next);
    updateLangChrome();
    refreshVoiceWarning();
    if (pastCount > 0) { refreshList(); }
  }
  async function init() {
    el("startBtn").addEventListener("click", startNew);
    el("continueLastBtn").addEventListener("click", continueLast);
    el("micBtn").addEventListener("click", toggleGoalMic);
    el("langToggle").addEventListener("click", toggleLanguage);
    el("pastToggle").addEventListener("click", function () { pastOpen = !pastOpen; renderPastToggle(); });
    document.addEventListener("blackout:restart", refreshList);
    window.addEventListener("beforeunload", function () {
      if (goalRecorder) { goalRecorder.cancel(); goalRecorder = null; goalRecording = false; }
    });
    updateLangChrome();
    el("goalInput").value = "";
    refreshList();
    refreshVoiceWarning();
  }
  document.addEventListener("DOMContentLoaded", init);
  return { backToStart: backToStart, refreshList: refreshList };
})();
", "path": "app/static/js/start.js"}, {"content": ""use strict";
window.BlackoutBlack = (function () {
  const STORAGE_KEY = "blackout_active_session_id";
  let sessionId = "";
  let sessionGoal = "";
  let socket = null;
  let capture = null;
  let recorder = null;
  let mode = "realtime";
  let paused = false;
  let finishing = false;
  let entered = false;
  let readySeen = false;
  let fallbackSeen = false;
  let intentionalClose = false;
  let wasFullscreen = false;
  let skipFullscreen = false;
  let wakeLock = null;
  let resumedEntry = false;
  let speechEpoch = 0;
  let speechChain = Promise.resolve();
  let ttsPlaying = false;
  let readyTimer = 0;
  let pollTimer = 0;
  let hintTimer = 0;
  let hintRemoveTimer = 0;
  let longPressTimer = 0;
  let suppressTapUntil = 0;
  let pttRecording = false;
  let pttStarting = false;
  let flowGeneration = 0;
  function el(id) { return document.getElementById(id); }
  function t(key, values) { return window.BlackoutI18n.t(key, values); }
  function serverErrorText(data) {
